/**
 * =============================================================================
 * FILE: src/components/GettingStartedTour.jsx
 * VERSION: v1 (initial)
 * =============================================================================
 * PURPOSE
 *   Shows the getting-started tour (public/guide/tour.html — slides with real
 *   screenshots, an Everyday / Owner path choice, and What's new) in a
 *   full-screen layer over the dashboard, and decides when to open it on
 *   its own.
 *
 * HOW THE TOUR STAYS CURRENT
 *   tour.html, its screenshots and guide/version.json are generated by
 *   guides/run.py, which GitHub Actions re-runs on every update. This
 *   component never hardcodes slide content; it only loads the page.
 *
 * WHEN IT OPENS BY ITSELF (useTourAutoOpen)
 *   - First time on a device: the welcome screen (choose a path).
 *   - After an update that added a new CHANGELOG.md entry: What's new, once.
 *   The "seen" marker is per device (localStorage key TOUR_SEEN_KEY, holding
 *   the What's-new version last shown). It's a convenience only: if storage
 *   is blocked the tour just doesn't auto-open, and it's always available
 *   from ⋮ › Getting started tour.
 *
 * CLOSING
 *   The tour page posts {type:'tour:close'} to this window (same origin)
 *   when its Close / Done buttons are tapped; Escape inside it does too.
 *
 * EDGE CASES
 *   - version.json missing (e.g. local dev before the guides are built):
 *     nothing auto-opens; the menu item still loads tour.html if present.
 *   - TOUR_SEEN_KEY === 'capture' is set by the screenshot script so the
 *     tour never covers the screens being captured.
 * =============================================================================
 */

import { useEffect, useState } from 'react'

export const TOUR_SEEN_KEY = 'dayforge-tour-seen' // localStorage: What's-new version last shown on this device
const TOUR_URL = '/guide/tour.html'
const VERSION_URL = '/guide/version.json'

function readSeen() {
  try { return localStorage.getItem(TOUR_SEEN_KEY) } catch { return 'unavailable' } // blocked storage: never auto-open
}
function writeSeen(v) {
  try { localStorage.setItem(TOUR_SEEN_KEY, v || 'none') } catch { /* per-device convenience only */ }
}

/**
 * Decides whether the tour should open by itself on this visit.
 * @returns {[string|null, Function, string|null]} [mode, setMode, version]:
 *   mode is null (closed), 'start' or 'whats-new'.
 */
export function useTourAutoOpen() {
  const [mode, setMode] = useState(null)
  const [version, setVersion] = useState(null)

  useEffect(() => {
    let cancelled = false
    fetch(VERSION_URL, { cache: 'no-store' })
      .then((r) => (r.ok ? r.json() : null))
      .then((info) => {
        if (cancelled || !info) return
        setVersion(info.version || null)
        const seen = readSeen()
        if (seen === 'capture' || seen === 'unavailable') return
        if (!seen) setMode('start')
        else if (info.version && info.whatsNew && seen !== info.version) setMode('whats-new')
      })
      .catch(() => { /* offline or not built yet: no auto-open */ })
    return () => { cancelled = true }
  }, [])

  return [mode, setMode, version]
}

/**
 * Full-screen tour layer.
 * @param {object} props
 * @param {'start'|'whats-new'} props.mode - which screen to open on.
 * @param {string|null} props.version - What's-new version to mark as seen on close.
 * @param {() => void} props.onClose
 */
export default function GettingStartedTour({ mode, version, onClose }) {
  useEffect(() => {
    function onMessage(e) {
      if (e.origin !== window.location.origin || e.data?.type !== 'tour:close') return
      writeSeen(e.data.version || version)
      onClose()
    }
    window.addEventListener('message', onMessage)
    return () => window.removeEventListener('message', onMessage)
  }, [version, onClose])

  return (
    <div
      className="fixed inset-0 z-[90] bg-[var(--color-ink)]"
      style={{
        paddingTop: 'env(safe-area-inset-top)',
        paddingBottom: 'env(safe-area-inset-bottom)',
        paddingLeft: 'env(safe-area-inset-left)',
        paddingRight: 'env(safe-area-inset-right)',
      }}
      role="dialog"
      aria-modal="true"
      aria-label="Getting started tour"
    >
      <iframe
        src={TOUR_URL + (mode === 'whats-new' ? '#whats-new' : '')}
        title="Getting started tour"
        className="w-full h-full border-0 block"
        // Focus the tour once loaded so its keyboard shortcuts (Escape to
        // close, arrow keys to step) work without clicking into it first.
        onLoad={(e) => { try { e.currentTarget.contentWindow.focus() } catch { /* same origin; ignore */ } }}
      />
    </div>
  )
}
